mapper.select:
select id from im_channel
 where status = 3 and del_flag = 0 and purge_at is not null and purge_at < #{now}
 order by purge_at, id
 limit #{limit}

mapper.update:
update im_channel
   set status = 4, meta_version = meta_version + 1, update_time = current_timestamp(3)
 where id = #{channelId} and status = 3 and purge_at is not null and purge_at < #{now}
